using System.Text.Json;

namespace SForce.Core;

public static class ForceCssBuilder
{
    public static string Build(ForceProfile profile)
    {
        var latin = CssString(profile.LatinFamily);
        var arabic = CssString(profile.ArabicFamily);

        return $$"""
            /* Generated by SFORCE. Icon fonts and code blocks are deliberately preserved. */
            :root {
              --sforce-latin: {{latin}};
              --sforce-arabic: {{arabic}};
            }

            html, body, button, input, textarea, select, option,
            div, span:not([class*="icon" i]):not(.material-icons):not(.material-symbols-outlined),
            p, a, li, td, th, label, blockquote,
            h1, h2, h3, h4, h5, h6 {
              font-family: var(--sforce-latin), var(--sforce-arabic), sans-serif !important;
              font-feature-settings: "kern" 1, "liga" 1;
              text-rendering: optimizeLegibility;
            }

            :lang(fa), :lang(ar), :lang(ur), :lang(ps),
            [lang^="fa"], [lang^="ar"], [lang^="ur"], [lang^="ps"] {
              font-family: var(--sforce-arabic), var(--sforce-latin), sans-serif !important;
            }

            code, pre, kbd, samp, textarea[data-code], .monaco-editor,
            .CodeMirror, [class*="code-block" i] {
              font-family: "SF Mono", "Cascadia Code", Consolas, monospace !important;
            }
            """;
    }

    private static string CssString(string value) => JsonSerializer.Serialize(value);
}
